#!/bin/sh
# Hand the approved queue to the press dispatcher.
echo "enqueue press queue at $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> .effects.log

arguments.command:
python3 - <<'PY'
import itertools, subprocess

# The 6 jobs originally in the queue
jobs = ["J-401","J-415","J-402","J-409","J-418","J-407"]

def check(q):
    open("queue.txt","w").write("\n".join(q)+"\n")
    r = subprocess.run(["python3","audit.py"],capture_output=True,text=True)
    return r.returncode==0, (r.stdout+r.stderr).strip()

# 1) Permutations of the exact 6 jobs
sols=[]
for perm in itertools.permutations(jobs):
    ok,msg=check(list(perm))
    if ok: sols.append(list(perm))
print("Permutation solutions (all 6 jobs):",len(sols))
for s in sols[:5]: print("  ",s)
PY
